citation(eu_dec_2021_914_art_1, [label - 'Commission Implementing Decision (EU) 2021/914 Art 1(1) (standard contractual clauses as appropriate safeguards; data exporter and data importer)', ref - 'CELEX:32021D0914, unit 32021D0914#art1, paragraph 1', verbatim - 'The standard contractual clauses set out in the Annex are considered to provide appropriate safeguards within the meaning of Article 46(1) and (2)(c) of Regulation (EU) 2016/679']).
citation(eu_dec_2021_914_annex_cl_1_b, [label - 'Commission Implementing Decision (EU) 2021/914 Annex, Clause 1(b) (the Parties have agreed to the Clauses)', ref - 'CELEX:32021D0914, unit 32021D0914#annex_cl1_b', verbatim - 'The Parties']).
citation(eu_dec_2021_914_annex_cl_1_b_i, [label - 'Commission Implementing Decision (EU) 2021/914 Annex, Clause 1(b)(i) (definition of data exporter)', ref - 'CELEX:32021D0914, unit 32021D0914#annex_cl1_b_i', verbatim - 'transferring the personal data, as listed in Annex I.A']).
