citation(eu_dec_2021_914_annex_cl_2_a, [label - 'Commission Implementing Decision (EU) 2021/914 Annex, Clause 2(a) (Clauses not modified except to select the Module or complete the Appendix; added clauses must not contradict)', ref - 'CELEX:32021D0914, unit 32021D0914#annex_cl2_a', verbatim - 'provided they are not modified, except to select the appropriate Module(s) or to add or update information in the Appendix']).
